// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.Set;

import org.junit.jupiter.api.Test;

/**
 * A query with many triple patterns is a left-deep chain of {@link Join}s, far deeper than the Java stack allows for
 * one call frame per join when collecting binding names.
 */
class JoinBindingNamesTest {

	private static StatementPattern pattern(int i) {
		return new StatementPattern(new Var("s" + i), new Var("p"), new Var("o" + i));
	}

	private static Join leftDeepChain(int patterns) {
		TupleExpr expr = pattern(0);
		for (int i = 1; i < patterns; i++) {
			expr = new Join(expr, pattern(i));
		}
		return (Join) expr;
	}

	@Test
	void bindingNamesOfAVeryDeepJoinChain() {
		Join join = leftDeepChain(200_000);
		Set<String> names = join.getBindingNames();
		assertThat(names).hasSize(2 * 200_000 + 1);
		assertThat(names).startsWith("s0", "p", "o0", "s1", "o1");
		assertThat(join.getAssuredBindingNames()).isEqualTo(names);
	}

	@Test
	void subclassesCollectTheirOwnArgumentsAndNestedSubclassesKeepTheirOverride() {
		Join nested = new Join(pattern(2), pattern(3)) {
			@Override
			public Set<String> getBindingNames() {
				return Set.of("custom");
			}
		};
		Join root = new Join(pattern(1), nested) {
		};
		assertThat(root.getBindingNames()).containsExactly("s1", "p", "o1", "custom");
		assertThat(root.getAssuredBindingNames()).containsExactly("s1", "p", "o1", "s2", "o2", "s3", "o3");
	}

	@Test
	void bindingNamesKeepLeftToRightOrderAndDeduplicate() {
		Join join = new Join(new Join(pattern(1), pattern(2)), new Join(pattern(2), pattern(3)));
		assertThat(join.getBindingNames()).containsExactly("s1", "p", "o1", "s2", "o2", "s3", "o3");
		assertThat(join.getAssuredBindingNames()).containsExactly("s1", "p", "o1", "s2", "o2", "s3", "o3");
	}
}
